int sock_read_data(struct sock *sk, read_descriptor_t *desc, sk_read_actor_t recv_actor)
{
    int copied = 0;
    struct sk_buff *skb;
    const struct skb_shared_info *shi;
    int inq;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    while ((skb = skb_peek(sk->sk_receive_queue)) != NULL) {
        int offset = 0;
        int len;

        len = skb->len - skb->data_len;
        if (len <= 0)
            return -EINVAL;

        shi = skb_shinfo(skb);
        inq = len;

        while (offset < len) {
            int copy = len - offset;
            int err;

            if (copy > (int)desc->count)
                copy = desc->count;

            if (copy <= 0)
                break;

            if (shi->nr_frags) {
                if (skb_copy_datagram_from_skb(desc->buf, desc->pos, skb, offset, copy))
                    return -EFAULT;
            } else {
                if (skb_copy_datagram_iovec(skb, offset, desc->iov, desc->iov_offset, copy))
                    return -EFAULT;
            }

            desc->pos += copy;
            desc->count -= copy;
            offset += copy;
            copied += copy;
        }

        if (copied)
            __skb_unlink(skb, &sk->sk_receive_queue);

        if (desc->count == 0)
            break;
    }

    if (copied)
        tcp_adjust_rcv_space(sk, copied);

    return copied;
}

int sock_read(struct sock *sk, read_descriptor_t *desc, sk_read_actor_t recv_actor)
{
    int copied = 0;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    while (1) {
        struct sk_buff *skb;
        const struct skb_shared_info *shinfo;
        int frag_idx;
        int copy;

        skb = skb_peek(&sk->sk_receive_queue);
        if (!skb)
            break;

        shinfo = skb_shinfo(skb);
        for (frag_idx = 0; frag_idx < shinfo->nr_frags; ) {
            const skb_frag_t *frag;
            int end;
            u32 offset;
            int err;

            frag = &shinfo->frags[frag_idx];
            offset = 0;
            end = skb_frag_size(frag);

            copy = min_t(int, end, desc->count);

            if (copy <= 0)
                break;

            err = recv_actor(desc, skb, (int)offset, copy);
            if (err < 0) {
                if (!copied)
                    return err;
                return (copied > 0) ? copied : err;
            }

            copied += copy;
            desc->count -= copy;
            offset += copy;
            frag_idx++;
        }

        if (skb->len <= desc->count)
            continue;

        copy = min_t(int, skb->len, desc->count);
        int err = recv_actor(desc, skb, 0, copy);
        if (err < 0) {
            if (!copied)
                return err;
            return (copied > 0) ? copied : err;
        }

        copied += copy;
        desc->count -= copy;
    }

    return copied ? copied : -EFAULT;
}

int sock_read_data(struct sock *sk, read_descriptor_t *desc, sk_read_actor_t recv_actor)
{
    int copied = 0;
    struct sk_buff *skb;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    while ((skb = skb_dequeue(&sk->sk_receive_queue)) != NULL) {
        const unsigned char *from;
        int len = skb->len;
        unsigned int offset = 0;

        while (len > 0) {
            int copy = min(len, desc->count);
            from = skb->data + offset;

            if (copy < 0)
                break;

            if (copy > 0) {
                int err = recv_actor(desc, from, copy, 0);
                if (err < 0) {
                    if (!copied)
                        copied = err;
                    break;
                }
                copied += copy;
                desc->count -= copy;
                offset += copy;
                len -= copy;
            }
        }

        if (skb->len - offset)
            skb_pull(skb, offset);
        else
            kfree_skb(skb);
    }

    tcp_rcv_space_adjust(sk);
    return copied;
}

int sock_read(struct sock *sk, read_descriptor_t *desc, sk_read_actor_t recv_actor)
{
    int copied = 0;
    struct sk_buff *skb;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    while ((skb = tcp_recv_skb(sk)) != NULL) {
        int len = skb->len;
        int offset = 0;

        while (offset < len) {
            int seg_len = len - offset;
            int err;

            err = recv_actor(desc, skb->data + offset, seg_len);
            if (err < 0) {
                if (!copied)
                    copied = err;
                break;
            }

            copied += err;
            offset += err;
        }

        tcp_clean_rbuf(sk);
        tcp_space(sk);
    }

    return copied;
}

int tcp_read_sock(struct sock *sk, read_descriptor_t *desc, sk_read_actor_t recv_actor)
{
    int copied = 0;
    struct sk_buff *skb, *head_skb = NULL;
    unsigned int copied_seq, target;
    int err = 0;

    if (sk->sk_state == TCP_LISTEN)
        return -EINVAL;

    copied_seq = sk->sk_rcv_nxt;
    target = desc->count;

    while (copied < target) {
        skb = skb_peek(&sk->sk_receive_queue);
        if (!skb)
            break;

        if (TCP_SKB_CB(skb)->seq == copied_seq) {
            int skb_len = skb->len;

            if (skb_len) {
                if (skb == head_skb)
                    head_skb = NULL;

                if ((err = recv_actor(desc, skb->data, skb_len)) < 0)
                    break;

                copied += err;
                copied_seq += err;
            }
        } else if (TCP_SKB_CB(skb)->seq < copied_seq) {
            if ((TCP_SKB_CB(skb)->end_seq - TCP_SKB_CB(skb)->seq) <= (copied_seq - TCP_SKB_CB(skb)->seq)) {
                __skb_unlink(skb, &sk->sk_receive_queue);
                kfree_skb(skb);
            } else {
                skb_split(skb, copied_seq - TCP_SKB_CB(skb)->seq, GFP_ATOMIC);
            }
        } else {
            break;
        }
    }

    if (copied)
        tcp_rcv_space_adjust(sk, copied);

    sk->sk_rcv_nxt = copied_seq;

    return copied ? copied : err;
}
